<?php require_once __DIR__.'/lib.php'; ?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AB Premiere | Administración</title><link rel="stylesheet" href="assets/style.css"></head><body><header><div class="brand"><img src="assets/logo-ab-premiere.png">AB PREMIERE · ADMIN</div><a href="/">← Portal</a></header><main class="wrap"><section id="login" class="card" style="max-width:430px;margin:60px auto"><h1>Acceso administrativo</h1><form id="loginForm"><label>Usuario</label><input id="user" value="admin"><label>Contraseña</label><input id="pass" type="password"><button class="btn wide">Entrar</button></form><div id="loginMsg"></div><p class="muted">Inicial: admin / ABPremier2026</p></section>
<section id="app" class="hidden"><div style="display:flex;justify-content:space-between;align-items:center"><div><h1>Panel administrativo</h1><span id="sessionInfo" class="muted"></span></div><button class="btn alt" onclick="logout()">Cerrar sesión</button></div><nav class="nav"><button class="btn active" onclick="view('dashboard',this)">Principal</button><button class="btn" onclick="view('clients',this)">Clientes</button><button class="btn" onclick="view('visits',this)">Visitas</button><button class="btn" onclick="view('catalogs',this)">Barberos y cortes</button><button class="btn" onclick="view('courtesies',this)">Cortesías</button><button class="btn" onclick="view('admins',this)">Usuarios administrativos</button><button class="btn" onclick="view('audit',this)">Bitácora</button></nav>
<div id="dashboard" class="view active"><div id="metrics" class="metrics"></div><div class="grid2" style="margin-top:16px"><div class="card"><h2>Visitas últimos 31 días</h2><div id="chart" class="chart"></div><h3>Porcentaje de visitas por día</h3><div id="weekdayStats" class="weekday-stats"></div></div><div class="card"><h2>Próximas cortesías</h2><div id="upcoming"></div></div></div><div class="grid2" style="margin-top:16px"><div class="card"><h2>Clientes sin asistir</h2><div id="absent"></div></div><div class="card"><h2>Cumpleañeros del mes</h2><div id="birthdays"></div></div></div></div>
<div id="clients" class="view"><div class="card"><div style="display:flex;justify-content:space-between"><h2>Clientes completos</h2><input id="clientSearch" class="inline" placeholder="Buscar" oninput="renderClients()"></div><div class="scroll"><table><thead><tr><th>Nombre</th><th>Código</th><th>Nacimiento</th><th>Teléfono</th><th>Registro</th><th>Última visita</th><th>Cortes</th><th>Puntos</th><th>Estado</th><th></th></tr></thead><tbody id="clientRows"></tbody></table></div></div></div>
<div id="visits" class="view"><div class="card"><div style="display:flex;justify-content:space-between;gap:12px;align-items:center"><h2>Panel de visitas</h2><a class="btn" id="excelLink" href="export.php">Descargar reporte completo en Excel</a></div><div class="grid4"><div><label>Desde</label><input id="from" type="date"></div><div><label>Hasta</label><input id="to" type="date"></div><div><label>Barbero</label><select id="filterBarber"></select></div><div><label>Corte</label><select id="filterService"></select></div></div><p><button class="btn" onclick="loadVisits()">Aplicar filtros</button> <button class="btn alt" onclick="quickRange(0)">Hoy</button> <button class="btn alt" onclick="quickRange(7)">Semana</button> <button class="btn alt" onclick="quickRange(31)">Mes</button></p><div class="scroll"><table><thead><tr><th>Fecha</th><th>Cliente</th><th>Código</th><th>Barbero</th><th>Corte</th><th>Puntos</th><th># Visita</th><th>Cortesía</th></tr></thead><tbody id="visitRows"></tbody></table></div></div></div>
<div id="catalogs" class="view"><div class="grid2"><div class="card"><h2>Barberos</h2><div class="grid2"><input id="barberName" placeholder="Nuevo barbero"><button class="btn" onclick="saveCatalog('barber')">Agregar</button></div><div id="barberList" class="scroll"></div></div><div class="card"><h2>Cortes y servicios</h2><input id="serviceName" placeholder="Nombre del nuevo servicio"><input id="serviceDescription" placeholder="Descripción"><div class="grid2"><input id="servicePrice" type="number" step=".01" placeholder="Precio"><input id="servicePoints" type="number" value="50" placeholder="Puntos"></div><button class="btn wide" onclick="saveCatalog('service')">Agregar servicio</button><div id="serviceList" class="scroll"></div></div></div></div>
<div id="courtesies" class="view"><div class="card"><h2>Cortesías obtenidas</h2><div id="courtesyRows"></div></div></div><div id="admins" class="view"><div class="grid2"><div class="card"><h2>Crear usuario administrativo</h2><label>Nombre completo</label><input id="adminName"><label>Usuario</label><input id="adminUser"><label>Contraseña (mínimo 8 caracteres)</label><input id="adminPassword" type="password"><button class="btn wide" style="margin-top:15px" onclick="saveAdmin()">Crear usuario</button><div id="adminMessage"></div></div><div class="card"><h2>Usuarios administrativos</h2><div id="adminRows"></div></div></div></div><div id="audit" class="view"><div class="card"><div style="display:flex;justify-content:space-between;align-items:center"><div><h2>Bitácora del sistema</h2><p class="muted">Registro de altas, cambios, visitas, cortesías y exportaciones.</p></div><button class="btn alt" onclick="loadAudit()">Actualizar</button></div><div class="scroll"><table><thead><tr><th>Fecha</th><th>Usuario</th><th>Acción</th><th>Elemento</th><th>ID</th><th>Detalle</th></tr></thead><tbody id="auditRows"></tbody></table></div></div></div></section></main><footer>AB PREMIERE · Administración</footer>
<div id="listModal" class="modal hidden"><div class="card"><button class="btn alt" style="float:right" onclick="$('listModal').classList.add('hidden')">Cerrar</button><h2 id="modalTitle"></h2><div id="modalBody"></div></div></div>
<script>const $=x=>document.getElementById(x),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let dash=null,cats=null;async function api(a,data=null,query=''){const r=await fetch(`api.php?action=${a}${query}`,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):null}),j=await r.json();if(r.status===401){showLogin();throw Error(j.message)}if(!r.ok)throw Error(j.message);return j}function msg(id,t,e=false){$(id).innerHTML=`<div class="message ${e?'error':''}">${t}</div>`}function showLogin(){$('login').classList.remove('hidden');$('app').classList.add('hidden')}$('loginForm').onsubmit=async e=>{e.preventDefault();try{await api('admin_login',{username:$('user').value,password:$('pass').value});boot()}catch(x){msg('loginMsg',esc(x.message),true)}};async function boot(){const s=await api('admin_session');if(!s.authenticated)return showLogin();$('login').classList.add('hidden');$('app').classList.remove('hidden');$('sessionInfo').textContent=s.user.username+' · '+s.user.role;await Promise.all([loadDashboard(),loadCatalogs(),loadVisits(),loadCourtesies(),loadAdmins(),loadAudit()])}function view(id,b){document.querySelectorAll('.view,.nav .btn').forEach(x=>x.classList.remove('active'));$(id).classList.add('active');b.classList.add('active')}
async function loadDashboard(){dash=await api('dashboard');const m=dash.metrics,items=[['Clientes activos',m.active,'all'],['Visitas hoy',m.today,'today'],['Nuevos este mes',m.new,'new'],['Sin asistir',m.absent,'absent'],['Al menos 1 al mes',m.monthly,'monthly'],['Frecuentes 2–3/mes',m.frequent,'frequent'],['Próximas cortesías',m.upcoming,'upcoming'],['Cumpleañeros',m.birthdays,'birthdays']];$('metrics').innerHTML=items.map(x=>`<div class="card metric" onclick="showList('${x[2]}','${x[0]}')">${x[0]}<b>${x[1]}</b><small>Ver lista →</small></div>`).join('');renderClients();const days=Object.entries(dash.daily),max=Math.max(1,...days.map(x=>x[1]));$('chart').innerHTML=days.length?days.map(x=>`<div class="bar" style="height:${x[1]/max*100}%" data-tip="${x[0]}: ${x[1]}"></div>`).join(''):'Sin visitas';const dayNames=['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'];$('weekdayStats').innerHTML=dayNames.map((n,i)=>`<div><span>${n}</span><div class="percent-track"><i style="width:${dash.weekday_percentages[i]}%"></i></div><b>${dash.weekday_percentages[i]}%</b></div>`).join('');$('upcoming').innerHTML=smallList(dash.lists.upcoming);$('absent').innerHTML=smallList(dash.lists.absent);$('birthdays').innerHTML=smallList(dash.lists.birthdays)}function smallList(a){return a.length?a.slice(0,8).map(x=>`<p><b>${esc(x.full_name)}</b><br><span class="muted">${esc(x.code)} · ${x.visits} cortes</span></p>`).join(''):'<p class="muted">Sin registros.</p>'}function showList(key,title){const a=key==='all'?dash.clients:dash.lists[key]||[];$('modalTitle').textContent=title;$('modalBody').innerHTML=smallList(a);$('listModal').classList.remove('hidden')}
function renderClients(){if(!dash)return;const q=$('clientSearch').value.toLowerCase();$('clientRows').innerHTML=dash.clients.filter(x=>(x.full_name+x.code+x.phone).toLowerCase().includes(q)).map(x=>`<tr><td><input class="inline" id="cn${x.id}" value="${esc(x.full_name)}"></td><td><b>${x.code}</b></td><td><input class="inline" id="cb${x.id}" type="date" value="${x.birth_date||''}"></td><td><input class="inline" id="cp${x.id}" value="${esc(x.phone)}"></td><td>${x.created_at.slice(0,10)}</td><td>${esc(x.last_visit||'—')}</td><td>${x.visits}</td><td>${x.points}</td><td><input id="ca${x.id}" type="checkbox" ${Number(x.active)?'checked':''}></td><td><button class="btn" onclick="saveClient(${x.id})">Guardar</button></td></tr>`).join('')}async function saveClient(id){await api('save_client',{id,full_name:$('cn'+id).value,birth_date:$('cb'+id).value,phone:$('cp'+id).value,active:$('ca'+id).checked});loadDashboard()}
async function loadCatalogs(){cats=await api('admin_catalogs');const activeBarbers=cats.barbers.filter(x=>Number(x.active)),activeServices=cats.services.filter(x=>Number(x.active));$('filterBarber').innerHTML='<option value="">Todos</option>'+activeBarbers.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');$('filterService').innerHTML='<option value="">Todos</option>'+activeServices.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');$('barberList').innerHTML=cats.barbers.map(x=>`<div class="catalog-edit"><input id="bn${x.id}" value="${esc(x.name)}"><label class="check"><input id="ba${x.id}" type="checkbox" ${Number(x.active)?'checked':''}> Activo</label><button class="btn" onclick="updateCatalog('barber',${x.id})">Guardar cambios</button></div>`).join('');$('serviceList').innerHTML=cats.services.map(x=>`<div class="catalog-edit"><input id="sn${x.id}" value="${esc(x.name)}"><input id="sd${x.id}" value="${esc(x.description||'')}" placeholder="Descripción"><div class="grid2"><input id="sp${x.id}" type="number" step=".01" value="${x.price}"><input id="st${x.id}" type="number" value="${x.points}"></div><label class="check"><input id="sa${x.id}" type="checkbox" ${Number(x.active)?'checked':''}> Activo</label><button class="btn" onclick="updateCatalog('service',${x.id})">Guardar cambios</button></div>`).join('')}
async function saveCatalog(type){const data=type==='barber'?{type,name:$('barberName').value}:{type,name:$('serviceName').value,description:$('serviceDescription').value,price:$('servicePrice').value,points:$('servicePoints').value};await api('save_catalog',data);if(type==='barber')$('barberName').value='';else $('serviceName').value=$('serviceDescription').value=$('servicePrice').value='';await loadCatalogs();loadAudit()}
async function updateCatalog(type,id){const data=type==='barber'?{type,id,name:$('bn'+id).value,active:$('ba'+id).checked}:{type,id,name:$('sn'+id).value,description:$('sd'+id).value,price:$('sp'+id).value,points:$('st'+id).value,active:$('sa'+id).checked};await api('save_catalog',data);await loadCatalogs();loadAudit()}function iso(d){return d.toISOString().slice(0,10)}function quickRange(days){const now=new Date(),start=new Date();start.setDate(now.getDate()-days);$('from').value=iso(start);$('to').value=iso(now);loadVisits()}async function loadVisits(){let q=`&from=${$('from').value}&to=${$('to').value}&barber_id=${$('filterBarber').value}&service_id=${$('filterService').value}`,d=await api('visits',null,q);excelLink.href='export.php?'+q.slice(1);$('visitRows').innerHTML=d.visits.map(x=>`<tr><td>${x.visited_at}</td><td>${esc(x.full_name)}</td><td>${x.code}</td><td>${esc(x.barber)}</td><td>${esc(x.service)}</td><td>${x.points_earned}</td><td>${x.visit_number}</td><td>${Number(x.courtesy_won)?'🎁 Sí':'No'}</td></tr>`).join('')}async function loadCourtesies(){const d=await api('courtesies');$('courtesyRows').innerHTML=d.courtesies.map(x=>`<p><b>${esc(x.full_name)}</b> · corte ${x.visit_number} · ${esc(x.status)} ${x.status==='pending'?`<button class="btn" onclick="redeem(${x.id})">Marcar entregada</button>`:''}</p>`).join('')||'Sin cortesías.'}async function redeem(id){await api('redeem',{id});loadCourtesies()}async function loadAdmins(){const d=await api('admins');$('adminRows').innerHTML=d.admins.map(x=>`<p><b>${esc(x.full_name||x.username)}</b><br><span class="muted">${esc(x.username)} · Alta: ${x.created_at.slice(0,10)} · Último acceso: ${esc(x.last_login||'Nunca')}</span></p>`).join('')}async function saveAdmin(){try{await api('save_admin',{full_name:$('adminName').value,username:$('adminUser').value,password:$('adminPassword').value});msg('adminMessage','Usuario creado correctamente.');$('adminName').value=$('adminUser').value=$('adminPassword').value='';loadAdmins()}catch(x){msg('adminMessage',esc(x.message),true)}}async function loadAudit(){const d=await api('audit_log');const labels={create:'Alta',update:'Edición',redeem:'Cortesía entregada',export:'Exportación',client:'Cliente',visit:'Visita',barbers:'Barbero',services:'Corte/servicio',admin:'Usuario',courtesy:'Cortesía',visits:'Visitas',complete_report:'Reporte completo'};$('auditRows').innerHTML=d.entries.map(x=>`<tr><td>${x.created_at}</td><td>${esc(x.admin_name)}</td><td>${esc(labels[x.action]||x.action)}</td><td>${esc(labels[x.entity]||x.entity)}</td><td>${x.entity_id||'—'}</td><td class="audit-detail">${esc(x.details||'—')}</td></tr>`).join('')}async function logout(){await api('admin_logout',{});location.reload()}boot();</script></body></html>
